import Foundation

/// Reads dashboard snapshots generated by the main app.
struct NomadFiWidgetSnapshotStore {

    private let userDefaults: UserDefaults?

    init(
        userDefaults: UserDefaults? = UserDefaults(
            suiteName: NomadFiWidgetSharedConstants.appGroupIdentifier
        )
    ) {
        self.userDefaults = userDefaults
    }

    func load() -> DashboardWidgetSnapshot {
        guard let userDefaults,
              let data = userDefaults.data(forKey: NomadFiWidgetSharedConstants.dashboardSnapshotKey),
              let snapshot = try? JSONDecoder().decode(DashboardWidgetSnapshot.self, from: data) else {
            return .placeholder
        }

        return snapshot
    }
}
